import {readFileSync}from 'node:fs';
import {resolve as resolvePath}from 'node:path';
import {pathToFileURL}from 'node:url';

// Existing, working helper. Preserve its exported behavior.
export function normalizeSegments(input){
  if(typeof input!=='string')throw Error('invalid path');
  const segments=[];
  for(const part of input.split('/')){
    if(part===''||part==='.')continue;
    if(part==='..'){segments.pop();continue;}
    segments.push(part);
  }
  return segments;
}

function assertRoot(root){
  if(typeof root!=='string')throw Error('root must be a string');
  if(root.length===0)throw Error('root must be nonempty');
  if(root.includes('\0'))throw Error('root must not contain a NUL byte');
  if(!root.startsWith('/'))throw Error('root must start with /');
}

function assertCandidate(candidate){
  if(typeof candidate!=='string')throw Error('candidate must be a string');
  if(candidate.length===0)throw Error('candidate must be nonempty');
  if(candidate.includes('\0'))throw Error('candidate must not contain a NUL byte');
}

export function resolveWithin(root,candidate){
  assertRoot(root);
  assertCandidate(candidate);
  const rootSegments=normalizeSegments(root);
  const segments=candidate.startsWith('/')
    ?normalizeSegments(candidate)
    :normalizeSegments(root+'/'+candidate);
  const resolved='/'+segments.join('/');
  let inside=true;
  for(let i=0;i<rootSegments.length;i++){
    if(segments[i]!==rootSegments[i]){inside=false;break;}
  }
  const relative=inside?segments.slice(rootSegments.length).join('/'):null;
  return {inside,resolved,relative};
}

function fail(message){
  process.stderr.write((message||'error')+'\n');
}

export function main(argv){
  try{
    if(!Array.isArray(argv)||argv.length!==1)
      throw Error('usage: node path-scope.js INPUT_JSON_FILE');
    const file=argv[0];
    if(typeof file!=='string'||file.length===0)
      throw Error('usage: node path-scope.js INPUT_JSON_FILE');
    let text;
    try{text=readFileSync(file,'utf8');}
    catch{throw Error('cannot read input file');}
    let data;
    try{data=JSON.parse(text);}
    catch{throw Error('input file is not valid JSON');}
    if(data===null||typeof data!=='object'||Array.isArray(data))
      throw Error('input JSON must be a non-null, non-array object');
    const result=resolveWithin(data.root,data.candidate);
    process.stdout.write(JSON.stringify(result)+'\n');
    return 0;
  }catch(err){
    const message=err instanceof Error?err.message:String(err);
    fail(message);
    return 2;
  }
}

if(typeof process.argv[1]==='string'&&process.argv[1]!==''){
  if(import.meta.url===pathToFileURL(resolvePath(process.argv[1])).href){
    process.exitCode=main(process.argv.slice(2));
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync}from 'node:child_process';
import {mkdtempSync,writeFileSync,rmSync}from 'node:fs';
import {tmpdir}from 'node:os';
import {join,dirname}from 'node:path';
import {fileURLToPath,pathToFileURL}from 'node:url';
import {normalizeSegments,resolveWithin}from '../path-scope.js';

const here=dirname(fileURLToPath(import.meta.url));
const modulePath=join(here,'..','path-scope.js');

function runCli(args){
  return spawnSync(process.execPath,[modulePath,...args],{encoding:'utf8'});
}

function withTempFile(content,fn){
  const dir=mkdtempSync(join(tmpdir(),'path-scope-'));
  const file=join(dir,'in.json');
  writeFileSync(file,content);
  try{return fn(file);}
  finally{rmSync(dir,{recursive:true,force:true});}
}

// --- normalizeSegments (existing behavior) ---
test('normalizeSegments: existing behavior preserved',()=>{
  assert.deepEqual(normalizeSegments('/a//b/./c'),['a','b','c']);
  assert.deepEqual(normalizeSegments('a/../../b'),['b']);
  assert.throws(()=>normalizeSegments(5),Error);
});

// --- resolveWithin: core containment ---
test('resolveWithin: spec examples',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','../ws/sub/../file.txt'),
    {inside:true,resolved:'/srv/ws/file.txt',relative:'file.txt'});
  assert.deepEqual(resolveWithin('/srv/ws','/srv/wsx'),
    {inside:false,resolved:'/srv/wsx',relative:null});
});

test('resolveWithin: absolute candidate inside',()=>{
  assert.deepEqual(resolveWithin('/a/b','/a/b/c/d'),
    {inside:true,resolved:'/a/b/c/d',relative:'c/d'});
});

test('resolveWithin: relative candidate inside with ..',()=>{
  assert.deepEqual(resolveWithin('/a/b','c/../d'),
    {inside:true,resolved:'/a/b/d',relative:'d'});
});

test('resolveWithin: same location yields empty relative',()=>{
  assert.deepEqual(resolveWithin('/a/b','/a/b'),
    {inside:true,resolved:'/a/b',relative:''});
  assert.deepEqual(resolveWithin('/a/b','.'),
    {inside:true,resolved:'/a/b',relative:''});
  assert.deepEqual(resolveWithin('/a/b/','/a/b'),
    {inside:true,resolved:'/a/b',relative:''});
});

test('resolveWithin: textual prefix sharing is outside',()=>{
  assert.deepEqual(resolveWithin('/a/b','/a/bc'),
    {inside:false,resolved:'/a/bc',relative:null});
  assert.deepEqual(resolveWithin('/a/b','abc'),
    {inside:false,resolved:'/a/b/abc',relative:'abc'});
});

test('resolveWithin: parent of root is outside',()=>{
  assert.deepEqual(resolveWithin('/a/b','/a'),
    {inside:false,resolved:'/a',relative:null});
  assert.deepEqual(resolveWithin('/a/b','..'),
    {inside:false,resolved:'/a',relative:null});
  assert.deepEqual(resolveWithin('/a/b','/'),
    {inside:false,resolved:'/',relative:null});
});

test('resolveWithin: a .. with nothing left is discarded',()=>{
  assert.deepEqual(resolveWithin('/a','/../../x'),
    {inside:false,resolved:'/x',relative:null});
  assert.deepEqual(resolveWithin('/','../../x'),
    {inside:true,resolved:'/x',relative:'x'});
});

test('resolveWithin: root of / contains everything',()=>{
  assert.deepEqual(resolveWithin('/','a/b'),
    {inside:true,resolved:'/a/b',relative:'a/b'});
  assert.deepEqual(resolveWithin('/','/a/b'),
    {inside:true,resolved:'/a/b',relative:'a/b'});
});

test('resolveWithin: backslash and dot-names are ordinary',()=>{
  const candidate='..foo/.../.hidden/x\\y';
  assert.deepEqual(resolveWithin('/a',candidate),
    {inside:true,resolved:'/a/..foo/.../.hidden/x\\y',
     relative:'..foo/.../.hidden/x\\y'});
  assert.deepEqual(resolveWithin('/a','.hidden'),
    {inside:true,resolved:'/a/.hidden',relative:'.hidden'});
});

test('resolveWithin: unnormalized root still compares correctly',()=>{
  assert.deepEqual(resolveWithin('/a/b/../c','x'),
    {inside:true,resolved:'/a/c/x',relative:'x'});
  assert.deepEqual(resolveWithin('/a/../a','b'),
    {inside:true,resolved:'/a/b',relative:'b'});
});

// --- validation ---
test('resolveWithin: invalid root throws',()=>{
  for(const bad of ['','a','a/','/a\0b','\0']){
    assert.throws(()=>resolveWithin(bad,'x'),Error);
  }
  assert.throws(()=>resolveWithin(5,'x'),Error);
  assert.throws(()=>resolveWithin(null,'x'),Error);
  assert.throws(()=>resolveWithin(undefined,'x'),Error);
});

test('resolveWithin: invalid candidate throws',()=>{
  for(const bad of ['','a\0b','\0']){
    assert.throws(()=>resolveWithin('/a',bad),Error);
  }
  assert.throws(()=>resolveWithin('/a',5),Error);
  assert.throws(()=>resolveWithin('/a',undefined),Error);
  assert.throws(()=>resolveWithin('/a',null),Error);
});

test('resolveWithin: does not mutate inputs',()=>{
  const root='/a/b';
  const candidate='c/../d';
  resolveWithin(root,candidate);
  assert.equal(root,'/a/b');
  assert.equal(candidate,'c/../d');
});

// --- CLI ---
test('cli: success prints one JSON value plus newline, exit 0, no stderr',()=>{
  const code=withTempFile(
    JSON.stringify({root:'/srv/ws',candidate:'../ws/sub/../file.txt'}),
    file=>{
      const r=runCli([file]);
      assert.equal(r.status,0);
      assert.equal(r.stderr,'');
      assert.ok(r.stdout.endsWith('\n'));
      assert.deepEqual(JSON.parse(r.stdout),
        {inside:true,resolved:'/srv/ws/file.txt',relative:'file.txt'});
      return r.status;
    });
  assert.equal(code,0);
});

test('cli: outside candidate exits 0 with null relative',()=>{
  withTempFile(JSON.stringify({root:'/srv/ws',candidate:'/srv/wsx'}),file=>{
    const r=runCli([file]);
    assert.equal(r.status,0);
    assert.deepEqual(JSON.parse(r.stdout),
      {inside:false,resolved:'/srv/wsx',relative:null});
  });
});

test('cli: extra JSON fields are ignored',()=>{
  withTempFile(JSON.stringify({root:'/a',candidate:'b',ignore:42}),file=>{
    const r=runCli([file]);
    assert.equal(r.status,0);
    assert.deepEqual(JSON.parse(r.stdout),
      {inside:true,resolved:'/a/b',relative:'b'});
  });
});

test('cli: wrong number of args exits 2, no stdout, stderr set',()=>{
  for(const args of [[],['a','b']]){
    const r=runCli(args);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  }
});

test('cli: missing input file exits 2, no stdout, stderr set',()=>{
  const r=runCli(['/no/such/file/anywhere.json']);
  assert.equal(r.status,2);
  assert.equal(r.stdout,'');
  assert.ok(r.stderr.length>0);
});

test('cli: invalid JSON exits 2, no stdout, stderr set',()=>{
  withTempFile('definitely not json',file=>{
    const r=runCli([file]);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  });
});

test('cli: JSON array or null exits 2',()=>{
  for(const content of ['[1,2]','null','"just a string"',
    JSON.stringify({root:'/a',candidate:'b'})+JSON.stringify({})]){
    // last item is two concatenated values -> invalid JSON overall
  }
  withTempFile('[1,2]',file=>{
    const r=runCli([file]);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  });
  withTempFile('null',file=>{
    const r=runCli([file]);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  });
  withTempFile('"just a string"',file=>{
    const r=runCli([file]);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  });
});

test('cli: invalid root in JSON exits 2, no stdout',()=>{
  for(const content of [
    JSON.stringify({root:'nope',candidate:'x'}),
    JSON.stringify({root:'/a',candidate:''}),
    JSON.stringify({root:'/a'}),
    JSON.stringify({candidate:'b'}),
  ]){
    withTempFile(content,file=>{
      const r=runCli([file]);
      assert.equal(r.status,2);
      assert.equal(r.stdout,'');
      assert.ok(r.stderr.length>0);
    });
  }
});

test('cli: NUL in JSON path value exits 2',()=>{
  withTempFile(JSON.stringify({root:'/a\0b',candidate:'x'}),file=>{
    const r=runCli([file]);
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  });
});

// --- importing must not run the CLI ---
test('importing the module does not run the CLI',()=>{
  const modUrl=pathToFileURL(modulePath).href;
  const r=spawnSync(process.execPath,['--input-type=module','-e',
    `import(${JSON.stringify(modUrl)});`],{encoding:'utf8'});
  assert.equal(r.status,0);
  assert.equal(r.stdout,'');
  assert.equal(r.stderr,'');
});

